 0; }\n  .autoriza { background: #fff7ed; border: 1px solid #fed7aa; border-left: 3.5px solid #f55400; }\n  .autoriza .statement-header { color: #c2410c; }\n  .autoriza .statement-text { color: #1e293b; }\n\n  /* Firma del trabajador */\n  .signature-container { margin-top: 18px; page-break-inside: avoid; }\n  .signature-card { width: 300px; margin: 0 auto; text-align: center; }\n  .sig-img-wrap { height: 70px; display: flex; align-items: flex-end; justify-content: center; margin-bottom: 4px; }\n  .sig-img { max-height: 65px; max-width: 240px; object-fit: contain; }\n  .firma-nota { display: inline-block; font-size: 7.5pt; color: #991b1b; font-weight: 600; background: #fee2e2; border: 1px solid #fca5a5; border-radius: 4px; padding: 4px 10px; line-height: 1.3; }\n  .sig-line { border-top: 1.5px solid #000b59; margin-bottom: 5px; }\n  .sig-name { font-size: 9pt; font-weight: 700; color: #000b59; text-transform: uppercase; }\n  .sig-details { font-size: 7.5pt; color: #64748b; line-height: 1.35; }\n\n  /* Pie de página */\n  .doc-footer { margin-top: 16px; border-top: 1px solid #e2e8f0; padding-top: 5px; display: flex; justify-content: space-between; font-size: 7pt; color: #94a3b8; page-break-inside: avoid; }\n\n  .statement-list { margin: 4px 0 6px 18px; font-size: 8.5pt; color: #334155; line-height: 1.45; }\n  .statement-list li { text-align: justify; margin-bottom: 3px; padding-left: 2px; }\n  .statement-list li::marker { color: #f55400; font-weight: 700; }\n\n  /* Tres firmas */\n  .signature-row { display: flex; justify-content: space-between; gap: 18px; }\n  .signature-row .signature-card { width: 32%; margin: 0; }\n  .sig-role { font-size: 7.5pt; font-weight: 700; color: #c2410c; text-transform: uppercase; letter-spacing: 0.3px; }\n\n  /* Acta en una sola hoja: espacios más compactos */\n  .metrics-card { margin-bottom: 10px; }\n  .metric-item { padding: 8px 14px; }\n  .section-block { margin-bottom: 8px; }\n  .section-title { margin-bottom: 5px; }\n  .data-grid td { padding: 4px 10px; }\n  .statement-box { padding: 8px 12px; margin-bottom: 8px; }\n  .signature-container { margin-top: 10px; }\n  .doc-footer { margin-top: 10px; }\n\n  /* v2: tablas pequeñas de restricciones y compromisos, tres firmas */\n  .mini-table { width: 100%; border-collapse: collapse; font-size: 7.8pt; margin-top: 2px; }\n  .mini-table th { background: #e6edf7; color: #000b59; font-weight: 700; text-align: left; padding: 3px 6px; border: 1px solid #cbd5e1; }\n  .mini-table td { padding: 3px 6px; border: 1px solid #e2e8f0; vertical-align: top; color: #1e293b; }\n  .resumen { font-size: 7.8pt; color: #475569; margin-top: 3px; font-weight: 600; }\n  .data-grid.dos td.data-label { width: 18%; }\n  .signature-row .signature-card { width: 31%; }\n  .sig-img-wrap { height: 56px; }\n  /* v2 en una hoja: más compacto */\n  body { font-size: 8.4pt; line-height: 1.35; }\n  .doc-header-table { margin-bottom: 8px; }\n  .logo-img { height: 40px; }\n  .header-title-cell { padding: 7px 12px; }\n  .section-block { margin-bottom: 6px; }\n  .section-title { margin-bottom: 4px; padding-bottom: 3px; }\n  .data-grid { font-size: 8pt; }\n  .data-grid td { padding: 2.5px 8px; }\n  .statement-box { padding: 6px 10px; margin-bottom: 6px; }\n  .statement-text { font-size: 8pt; line-height: 1.4; }\n  .signature-container { margin-top: 8px; }\n  .doc-footer { margin-top: 8px; }\n</style>\n</head>\n<body>\n\n  <table class="doc-header-table">\n    <tr>\n      <td class="header-logo-cell">\n        <img src="{{logo_src}}" alt="LOG&amp;SER" class="logo-img">\n      </td>\n      <td class="header-title-cell">\n        <div class="doc-title">ACTA DE CIERRE Y SEGUIMIENTO A CASO DE SALUD</div>\n        <div class="doc-subtitle">SEGURIDAD Y SALUD EN EL TRABAJO</div>\n        <div class="doc-subdetail">SEGUIMIENTO A CASOS DE SALUD</div>\n      </td>\n      <td class="header-meta-cell">\n        <div class="meta-code">{{codigo_formato}}</div>\n        <div class="meta-ver">Versión: {{version_formato}}</div>\n        <div class="meta-date">{{fecha_formato}}</div>\n        <div class="meta-id">CASO: {{codigo_caso}}</div>\n      </td>\n    </tr>\n  </table>\n\n  <section class="section-block">\n    <div class="section-title">1. Datos del colaborador</div>\n    <table class="data-grid dos">\n      <tr><td class="data-label">Colaborador:</td><td class="data-val"><strong>{{nombre_trabajador}}</strong></td><td class="data-label">Cédula:</td><td class="data-val">{{identificacion}}</td></tr>\n      <tr><td class="data-label">Cargo:</td><td class="data-val">{{cargo}}</td><td class="data-label">Área:</td><td class="data-val">{{area}}</td></tr>\n      <tr><td class="data-label">Regional / Operación:</td><td class="data-val">{{regional}} / {{operacion}}</td><td class="data-label">Fecha de ingreso:</td><td class="data-val">{{fecha_ingreso}}</td></tr>\n      <tr><td class="data-label">Jefe inmediato:</td><td class="data-val">{{jefe_inmediato}}</td><td class="data-label">Responsable SST:</td><td class="data-val">{{responsable_sst}}</td></tr>\n    </table>\n  </section>\n\n  <section class="section-block">\n    <div class="section-title">2. Información del evento y seguimiento laboral</div>\n    <table class="data-grid dos">\n      <tr><td class="data-label">Tipo de evento:</td><td class="data-val">{{tipo_evento}}</td><td class="data-label">Origen:</td><td class="data-val">{{origen}}</td></tr>\n      <tr><td class="data-label">Incapacidad:</td><td class="data-val">{{incapacidad}}</td><td class="data-label">Estado laboral:</td><td class="data-val">{{estado_laboral}}</td></tr>\n      <tr><td class="data-label">Último concepto:</td><td class="data-val">{{fecha_ultimo_concepto}} · {{tipo_concepto}}</td><td class="data-label">Calificación:</td><td class="data-val">{{proceso_calificacion}}</td></tr>\n      <tr><td class="data-label">Adaptación del puesto:</td><td class="data-val" colspan="3">{{adaptacion}}</td></tr>\n    </table>\n  </section>\n\n  <section class="statement-box autoriza">\n    <div class="statement-header">3. Restricciones y recomendaciones funcionales</div>\n    {{restricciones_html}}\n  </section>\n\n  <section class="section-block">\n    <div class="section-title">Información del cierre</div>\n    <table class="data-grid dos">\n      <tr><td class="data-label">Fecha de cierre:</td><td class="data-val">{{fecha_cierre}}</td><td class="data-label">Actividad final:</td><td class="data-val">{{actividad_actual}}</td></tr>\n      <tr><td class="data-label">Motivo de cierre:</td><td class="data-val" colspan="3">{{motivo_cierre}}</td></tr>\n    </table>\n  </section>\n\n  <section class="statement-box">\n    <div class="statement-header">4. Objeto del acta: cierre y seguimiento</div>\n    <p class="statement-text">Se deja constancia del cierre del seguimiento a este caso de salud en el Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST) de LOG&amp;SER S.A.S. Se verificó el estado de los compromisos registrados, la culminación o actualización del período de restricciones y recomendaciones, y las condiciones en que el colaborador continúa su labor, conforme a los conceptos médicos y la normatividad vigente. El colaborador declara haber recibido el acompañamiento de la empresa. Este documento no contiene información clínica.</p>\n  </section>\n\n  <section class="section-block">\n    <div class="section-title">5. Compromisos del caso</div>\n    {{compromisos_html}}\n    <div class="resumen">{{compromisos_resumen}}</div>\n  </section>\n\n  <section class="statement-box">\n    <div class="statement-header">6. Observaciones</div>\n    <p class="statement-text">{{observacion_administrativa}}</p>\n  </section>\n\n  <div class="signature-container">\n    <div class="signature-row">\n      <div class="signature-card">\n        <div class="sig-img-wrap">{{firma_trabajador}}</div>\n        <div class="sig-line"></div>\n        <div class="sig-role">Colaborador</div>\n        <div class="sig-name">{{nombre_trabajador}}</div>\n        <div class="sig-details">C.C. {{identificacion}}</div>\n      </div>\n      <div class="signature-card">\n        <div class="sig-img-wrap">{{firma_jefe}}</div>\n        <div class="sig-line"></div>\n        <div class="sig-role">Jefe inmediato</div>\n        <div class="sig-name">{{jefe_inmediato}}</div>\n        <div class="sig-details">{{operacion}}</div>\n      </div>\n      <div class="signature-card">\n        <div class="sig-img-wrap">{{firma_sst}}</div>\n        <div class="sig-line"></div>\n        <div class="sig-role">Líder SST</div>\n        <div class="sig-name">{{nombre_sst}}</div>\n        <div class="sig-details">{{cargo_sst}}</div>\n      </div>\n    </div>\n  </div>\n\n  <footer class="doc-footer">\n    <span>Cerrado por: {{usuario_cierre}} &bull; {{fecha_cierre}}</span>\n    <span>Certificación electrónica bajo Ley 527 de 1999</span>\n    <span>Generado el {{fecha_generacion}}</span>\n  </footer>\n\n</body>\n</html>\n'
WHERE nombre_proceso = 'acta_cierre_cm';
